import { Redis } from "@upstash/redis";

export type RateLimitTier = "standard" | "sensitive" | "ai" | "validation";

const tierConfigs: Record<RateLimitTier, { tokens: number; windowMs: number }> = {
  standard: { tokens: 60, windowMs: 60_000 },
  sensitive: { tokens: 10, windowMs: 60_000 },
  ai: { tokens: 5, windowMs: 60_000 },
  validation: { tokens: 20, windowMs: 60_000 },
};

const useRedis =
  !!process.env.UPSTASH_REDIS_REST_URL && !!process.env.UPSTASH_REDIS_REST_TOKEN;

let redis: Redis | null = null;
function getRedis(): Redis {
  if (!redis) {
    redis = new Redis({
      url: process.env.UPSTASH_REDIS_REST_URL!,
      token: process.env.UPSTASH_REDIS_REST_TOKEN!,
    });
  }
  return redis;
}

